function buildPrompt(co,qid){
  // Ultra-compact catalog: mã|tên|p1-p2-p3-p4-p5-p6 (~15 tokens/SP thay vì 50)
  let cat="";
  D.s.forEach(s=>{
    const vi=s.vi?"✓":"✗";
    cat+="\n["+s.n+"] VAT"+s.v+"%"+vi+" tiers:"+((s.tl||[]).join(","))+"\n";
    // Ghi chú quan trọng nhất (tối đa 1 dòng)
    if(s.notes&&s.notes.length){
      const n=s.notes.find(function(x){return x.toLowerCase().indexOf("vat")>=0||x.toLowerCase().indexOf("giá")>=0;});
      if(n)cat+=" 📌"+n.substring(0,80)+"\n";
    }
    s.p.forEach(p=>{
      const code=p.c||"";
      const name=(p.n||"").substring(0,55);
      const prices=(p.t&&p.t.length)?p.t.map(function(t){return fmtC(t.p);}).join("-"):"";
      cat+=(code?code+"|":"")+name+(prices?"|"+prices:"")+"\n";
    });
  });
  const q=qid||newQID();
  const tmpl='{"quoteNumber":"'+q+'","date":"'+today()+'","validUntil":"'+dateAfter(30)+'","customer":{"name":"","address":"","phone":""},"items":[{"stt":1,"code":"","name":"","unit":"Cái","quantity":0,"unitPrice":0,"amount":0,"tierUsed":""}],"subtotal":0,"vatRate":0,"vatIncluded":false,"vatAmount":0,"total":0,"notes":""}';
  return "Trợ lý báo giá tự động cho "+(co&&co.name?co.name:"VIVA")+".\n\n"+
    "QUY TẮC TUYỆT ĐỐI:\n"+
    "1. TẠO NGAY báo giá JSON khi người dùng nhắc đến BẤT KỲ sản phẩm nào — KHÔNG HỎI THÊM\n"+
    "2. Số lượng chưa có → dùng 100, ghi tierUsed=50-100\n"+
    "3. Thông tin khách hàng → để trống chuỗi rỗng, KHÔNG hỏi\n"+
    "4. LUÔN xuất QUOTE_JSON ngay lập tức, kể cả khi thiếu thông tin\n"+
    "5. Sau JSON: 1 câu tóm tắt ngắn + nhắc click nút [📝 Xuất Word]\n\n"+
    "CATALOG:"+cat+"\n"+
    "CÁCH TÍNH: amount=qty×price; vat=sub×vatRate/100; total=sub+vat\n"+
    "CHỌN BẬC GIÁ: 75 cái→50-100; 200→200-300; 600→501-1000\n"+
    "VAT: ✓=đã gộp ✗=chưa gộp\n"+     "GIÁ (QUAN TRỌNG): compact 300k=300000₫; 1.265M=1265000₫; 55k=55000₫\n"+     "Trong JSON PHẢI dùng số nguyên đầy đủ: unitPrice:300000 KHÔNG PHẢI 300 hay 300k\n"+"7. Tên SP trong JSON: dùng TÊN ĐẦY ĐỦ từ catalog, KHÔNG rút gọn\n\n"+
    "FORMAT BẮT BUỘC:\nQUOTE_JSON_START\n"+tmpl+"\nQUOTE_JSON_END";
}

